record.field:
errors = []
success = []
for country in records:
    try:
        country.action_sync_kiiraaye_geography()
        success.append(country.display_name)
    except Exception as exc:
        errors.append(f"{country.display_name}: {exc}")

message = f"Pays synchronisés : {len(success)}"
if errors:
    message += f"\nPays en erreur : {len(errors)}\n\n" + "\n".join(errors[:20])

if errors:
    notification_type = "warning"
else:
    notification_type = "success"

action = {
    "type": "ir.actions.client",
    "tag": "display_notification",
    "params": {
        "title": "Synchronisation géographique",
        "message": message,
        "type": notification_type,
        "sticky": bool(errors),
    },
}
